/**
 * The deployed browser entry must not drift from its source of truth.
 *
 * The browser loads `client/index.js` as a classic script, so it cannot import
 * the sibling modules; it carries copies instead. The copies are generated by
 * `scripts/sync-client.mjs`, and this test fails when the two files disagree —
 * which is how the panel copy drifted apart before: the module dropped two
 * fields on save while the copy the browser runs kept them.
 *
 * @module dsh-oauth-mcp/test/unit/client-sync
 */

import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { describe, it } from 'node:test'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..')

/**
 * Read one file of the package.
 *
 * @param {string} relative The path inside the package.
 * @returns {string} The content.
 */
function read(relative) {
  return readFileSync(join(root, relative), 'utf8')
}

/**
 * Take the part of a file between two markers.
 *
 * @param {string} source The file content.
 * @param {string} start The opening marker.
 * @param {string} end The closing marker.
 * @returns {string} The marked part.
 */
function between(source, start, end) {
  const from = source.indexOf(start)
  const to = source.indexOf(end)
  assert.ok(from >= 0, `the marker ${start} is missing`)
  assert.ok(to > from, `the marker ${end} is missing`)
  return source.slice(source.indexOf('\n', from) + 1, to)
}

/**
 * Normalise a code block for comparison.
 *
 * The copy drops the `export` keyword and the indentation; nothing else.
 *
 * @param {string} code The block.
 * @returns {string[]} The significant lines.
 */
function significantLines(code) {
  return code
    .replace(/^export\s+/gm, '')
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line !== '')
}

/**
 * Compare two blocks line by line.
 *
 * @param {string[]} expected The lines of the source.
 * @param {string[]} actual The lines of the copy.
 * @param {string} what The name of the block.
 * @returns {void}
 */
function assertSame(expected, actual, what) {
  assert.equal(actual.length, expected.length, `the ${what} copy has a different number of lines`)
  for (let index = 0; index < expected.length; index += 1) {
    assert.equal(actual[index], expected[index], `line ${index + 1} of the ${what} copy differs`)
  }
}

describe('the deployed browser entry', () => {
  it('carries the command row of the source of truth', () => {
    const source = between(
      read('client/commandview.js'),
      '// >>> SYNC_BLOCK',
      '// <<< SYNC_BLOCK',
    )
    const deployed = between(
      read('client/index.js'),
      '// >>> COMMAND_VIEW',
      '// <<< COMMAND_VIEW',
    )

    assertSame(significantLines(source), significantLines(deployed), 'command row')
  })

  it('carries the settings panel of the source of truth', () => {
    const source = between(
      read('client/panel.js'),
      '// >>> PANEL_BLOCK',
      '// <<< PANEL_BLOCK',
    )
    // The vendor code inside the region is written into the entry by the
    // vendor generator, so the copy leaves it out.
    const vendorFrom = source.indexOf('// >>> VENDOR_CODE')
    const vendorTo = source.indexOf('// <<< VENDOR_CODE')
    const parts = []
    if (vendorFrom >= 0 && vendorTo > vendorFrom) {
      parts.push(source.slice(0, vendorFrom))
      parts.push(source.slice(vendorTo + '// <<< VENDOR_CODE'.length))
    } else {
      parts.push(source)
    }
    const deployed = between(
      read('client/index.js'),
      '// >>> PANEL_VIEW',
      '// <<< PANEL_VIEW',
    )

    assertSame(
      significantLines(parts.join('\n')),
      significantLines(deployed),
      'settings panel',
    )
  })

  it('carries the tool views of the source of truth', () => {
    const source = between(
      read('client/toolview.js'),
      '// >>> TOOLVIEW_BLOCK',
      '// <<< TOOLVIEW_BLOCK',
    )
    const deployed = between(
      read('client/index.js'),
      '// >>> TOOL_VIEW',
      '// <<< TOOL_VIEW',
    )

    assertSame(significantLines(source), significantLines(deployed), 'tool view')
  })

  it('carries the helpers both components share', () => {    const source = between(
      read('client/panel.js'),
      '// >>> SHARED_HELPERS',
      '// <<< SHARED_HELPERS',
    )
    const deployed = between(
      read('client/index.js'),
      '// >>> SHARED_HELPERS',
      '// <<< SHARED_HELPERS',
    )

    assertSame(significantLines(source), significantLines(deployed), 'shared helpers')
  })
})
